import json

def run(_context):
    tools = mb.list_library_tools(contains='TIW')
    # Find flat end mills suitable for pocket roughing & finishing
    # Pocket is 60x60 with 5mm corner radius - need tool <= 10mm dia for corners
    print("=== Flat End Mills (dia <= 12mm) ===")
    for t in tools:
        if t['corner_radius_mm'] == 0.0 and t['diameter_mm'] <= 12.0 and t['diameter_mm'] >= 6.0:
            print(json.dumps(t))
    print()
    print("=== Larger Flat End Mills (12-20mm) for roughing ===")
    for t in tools:
        if t['corner_radius_mm'] == 0.0 and t['diameter_mm'] > 12.0 and t['diameter_mm'] <= 20.0:
            print(json.dumps(t))

